*** Add File: src/engine.mjs
+const GROUP_RULES = [
+  ['Digital access & connected services', /digital key|app|bluetooth|carplay|android|connected|remote|mobile|phone/i],
+  ['Intuitive controls & driver interaction', /operat|control|touch|display|cluster|parking brake|automatic-hold|speed limit|button|console|owner's manual|camera/i],
+  ['Cabin comfort & wellbeing', /seat|comfort|lumbar|climat|blower|acoustic|noise|audio|sound|belt|mirror/i],
+  ['Driving confidence & ride quality', /handling|riding|drivetrain|chassis|steer|brake|pedal|suspension|stability/i],
+  ['Electric mobility experience', /electric range|charging|battery|efficiency|range/i],
+  ['Exterior usability & expression', /exterior|roof|trunk|tailgate|light|door|paint|wheel/i],
+  ['Space, storage & everyday utility', /storage|luggage|cargo|compartment|space|fold|cupholder/i]
+];
+
+const ENTITY_RULES = [
+  ['Software & Connected Services', /app|digital|bluetooth|carplay|connected|remote|operating system|display|touch|camera/i],
+  ['Interior Engineering', /seat|comfort|lumbar|climat|blower|console|storage|mirror|belt|audio|sound/i],
+  ['Chassis Engineering', /handling|riding|chassis|steer|brake|pedal|suspension|stability/i],
+  ['E-Mobility Engineering', /electric|charging|battery|range|efficiency/i],
+  ['Body Engineering', /exterior|roof|trunk|tailgate|door|luggage|compartment|space/i]
+];
+
+const monthsFor = feature => /app|software|display|touch|operating|bluetooth|carplay|manual/i.test(feature) ? 6
+  : /seat|console|storage|mirror|belt|audio|climat|control|camera/i.test(feature) ? 12
+  : /chassis|suspension|body|roof|luggage|battery|drivetrain/i.test(feature) ? 24 : 15;
+
+export function groupFor(feature) {
+  return GROUP_RULES.find(([, rule]) => rule.test(feature))?.[0] || `Improve ${feature}`;
+}
+
+export function entityFor(feature) {
+  const match = ENTITY_RULES.find(([, rule]) => rule.test(feature));
+  return { name: match?.[0] || 'Product Integration', confidence: match ? 'medium' : 'low', reason: match ? `The feature classification “${feature}” matches this function’s typical ownership.` : 'Ownership crosses domains and requires PM confirmation.' };
+}
+
+function requirementStatement(feature, records) {
+  const types = new Set(records.map(r => r.feedbackType));
+  if ([...types].some(t => /Difficult/i.test(t))) return `Make ${feature.toLowerCase()} easier and more predictable to use`;
+  if ([...types].some(t => /Want/i.test(t))) return `Improve ${feature.toLowerCase()} to address documented customer requests`;
+  return `Preserve and strengthen customer satisfaction with ${feature.toLowerCase()}`;
+}
+
+export function buildModel(records, config, statuses = {}) {
+  const relevant = records.filter(r => r.vehicle === config.vehicle && r.market === config.market && r.quality !== 'low' && r.feature);
+  const byFeature = new Map();
+  for (const record of relevant) {
+    if (!byFeature.has(record.feature)) byFeature.set(record.feature, []);
+    byFeature.get(record.feature).push(record);
+  }
+  const maxFrequency = Math.max(1, ...[...byFeature.values()].map(items => new Set(items.map(x => x.feedbackId)).size));
+  const requirements = [...byFeature].map(([feature, items]) => {
+    const unique = [...new Map(items.map(item => [item.feedbackId, item])).values()];
+    const months = monthsFor(feature);
+    const peopleNeeded = Math.max(2, Math.ceil(months / 3));
+    const frequencyScore = Math.round((unique.length / maxFrequency) * 100);
+    const scheduleRatio = (config.months * Math.max(1, config.people)) / (months * peopleNeeded);
+    const fitScore = Math.round(Math.min(100, scheduleRatio * 70));
+    const importance = Number(config.importance) / 10;
+    let score = Math.round(frequencyScore * (0.75 - importance * 0.25) + fitScore * (0.25 + importance * 0.25));
+    if (statuses[feature] === 'not-feasible') score = -1;
+    if (statuses[feature] === 'conditional') score -= 12;
+    const owner = entityFor(feature);
+    return {
+      id: `req-${feature.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '')}`,
+      feature,
+      group: groupFor(feature),
+      statement: requirementStatement(feature, items),
+      frequency: unique.length,
+      score,
+      estimatedMonths: months,
+      estimatedPeople: peopleNeeded,
+      fitScore,
